using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Http;

namespace Filee.Web.Security;

/// <summary>
/// Application-level CSRF validation. This token is generated by the Web session and is deliberately
/// not an OIDC state value.
/// </summary>
public sealed class CsrfService
{
    public bool IsValid(HttpContext context, SessionIdentity identity)
    {
        ArgumentNullException.ThrowIfNull(context);
        ArgumentNullException.ThrowIfNull(identity);

        if (!context.Request.Cookies.TryGetValue(WebCookieNames.Csrf, out var cookieToken))
            return false;
        if (!context.Request.Headers.TryGetValue(WebCookieNames.CsrfHeader, out var headerValues))
            return false;

        return FixedTimeEquals(cookieToken, identity.CsrfToken)
            && FixedTimeEquals(headerValues.ToString(), identity.CsrfToken);
    }

    private static bool FixedTimeEquals(string? left, string? right)
    {
        if (left is null || right is null)
            return false;

        var leftBytes = Encoding.UTF8.GetBytes(left);
        var rightBytes = Encoding.UTF8.GetBytes(right);
        return CryptographicOperations.FixedTimeEquals(leftBytes, rightBytes);
    }
}
